INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'persuade', 'v.', '/pəˈsweɪd/', '说服;劝服', 'My teacher persuaded me to try ice hockey.', '我的老师说服我去尝试冰球。', 'On the Move', 44, 0, 'senior', 'wordlist', 'required2', 'U3', 'persuade sb to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'champion', 'n.', '/ˈtʃæmpiən/', '冠军;第一名', 'We hope to become national champions one day.', '我们希望有朝一日成为全国冠军。', 'On the Move', 45, 0, 'senior', 'wordlist', 'required2', 'U3', 'national champion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ultimate', 'adj.', '/ˈʌltɪmɪt/', '最终的;最后的', 'My ultimate goal is to become an ice hockey coach.', '我的最终目标是成为一名冰球教练。', 'On the Move', 46, 0, 'senior', 'wordlist', 'required2', 'U3', 'ultimate goal', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u3.01', '①不定式作定语(名词 + to do:something to eat / the first to do)', 'A2', 10, '外研社版必修第二册 U3 — 在名词或不定代词后用 to do 作后置定语,表示「该名词要做的/可做的事」;序数词、the only/last/next 后的名词也常接 to do。-ing/-ed/限定式都不能这样作定语。', 1, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u3.02', '②不定式作结果状语(too…to / enough to / so…as to)', 'A2', 10, '外研社版必修第二册 U3 — too + 形/副 + to do 表「太……以致不能」;形/副 + enough + to do 表「足够……可以」;so + 形/副 + as to do 表「如此……以致」。这些结构后只能跟 to do 表结果。', 2, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u3.03', '③不定式作目的状语与结果状语的对比(to do)', 'A2', 10, '外研社版必修第二册 U3 — to do 既可表目的(= in order to,「为了」),也可表结果(too…to / enough to / so…as to)。无论目的还是结果,空处都用 to do;-ing/-ed/限定式不能充当这一状语。', 3, 'required2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'Football is a simple game ____, which is one reason for its huge popularity.', 'to play', 'playing', 'played', 'plays', 'A', '名词 game 后用 to do 作定语,表示「可以玩的游戏」;-ing/-ed/限定式都不能这样作后置定语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'He was the first player ____ the winning goal in the final match.', 'scoring', 'to score', 'scored', 'scores', 'B', '序数词 the first 后的名词接 to do 作定语,意为「第一个进球的球员」。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'After the long match, we looked for something cold ____.', 'drinking', 'drunk', 'to drink', 'drinks', 'C', '不定代词 something 后用 to do 作定语,表示「可以喝的东西」。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'She is always the last one ____ the training ground every evening.', 'leaving', 'left', 'leaves', 'to leave', 'D', 'the last one 后接 to do 作定语,意为「最后一个离开的人」。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'I still have a lot of training ____ before the championship begins.', 'to do', 'doing', 'done', 'does', 'A', '名词 training 后用 to do 作定语,表示「要做的训练」。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'This app gives runners a good way ____ their daily progress.', 'charting', 'to chart', 'charted', 'charts', 'B', 'way 后用 to do 作定语,表示「记录进展的方法」。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'A skipping rope is a cheap piece of equipment ____ almost anywhere.', 'using', 'used', 'to use', 'uses', 'C', '名词 equipment 后用 to do 作定语,表示「可以使用的器材」。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'The coach gave us several new exercises ____ at home this week.', 'trying', 'tried', 'tries', 'to try', 'D', '名词 exercises 后用 to do 作定语,意为「可以尝试的练习」。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'Tai chi is a wonderful art ____ if you want to relax your mind.', 'to learn', 'learning', 'learned', 'learns', 'A', '名词 art 后用 to do 作定语,表示「值得学的一门艺术」。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'He was the only member of the team ____ for the gorilla run.', 'signing up', 'to sign up', 'signed up', 'signs up', 'B', 'the only member 后用 to do 作定语,意为「唯一报名的人」。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'There is no time ____; the marathon starts in ten minutes.', 'losing', 'lost', 'to lose', 'loses', 'C', '名词 time 后用 to do 作定语,no time to lose 意为「没有时间可浪费」。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'She bought a watch with a clear display ____ her heart rate.', 'monitoring', 'monitored', 'monitors', 'to monitor', 'D', '名词 display 后用 to do 作定语,表示「用来监测心率的显示屏」。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'Pull-ups are a great way ____ strength in your upper body.', 'to build', 'building', 'built', 'builds', 'A', 'way 后用 to do 作定语,表示「增强力量的方法」。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'The teacher was looking for a sport ____ to the whole PE class.', 'recommending', 'to recommend', 'recommended', 'recommends', 'B', '名词 sport 后用 to do 作定语,意为「可以推荐的运动」。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'Running gave him a real reason ____ out of bed early every day.', 'getting', 'got', 'to get', 'gets', 'C', '名词 reason 后用 to do 作定语,表示「早起的理由」。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'The club has plenty of ropes and bars ____ during training.', 'using', 'used', 'uses', 'to use', 'D', '名词 ropes and bars 后用 to do 作定语,意为「训练时可用的器材」。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'He is exactly the kind of champion ____ — humble and hard-working.', 'to admire', 'admiring', 'admired', 'admires', 'A', '名词 champion 后用 to do 作定语,表示「值得敬佩的冠军」。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'We need a quiet place ____ before the big game tonight.', 'resting', 'to rest', 'rested', 'rests', 'B', '名词 place 后用 to do 作定语,意为「可以休息的地方」。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'The plank is a simple exercise ____ almost anywhere, even at home.', 'doing', 'done', 'to do', 'does', 'C', '名词 exercise 后用 to do 作定语,表示「可以做的练习」。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.01'), 'She was the second runner ____ the finish line in the school race.', 'crossing', 'crossed', 'crosses', 'to cross', 'D', '序数词 the second 后的名词接 to do 作定语,意为「第二个冲线的人」。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'He was too tired ____, so he had to stop running.', 'to continue', 'continuing', 'continued', 'continues', 'A', 'too + 形 + to do 表「太累以致不能继续」,空处只能用 to do。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The ball is small enough ____ into most sports bags.', 'fitting', 'to fit', 'fitted', 'fits', 'B', '形 + enough + to do 表「足够小可以放进去」,空处用 to do 表结果。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'Football is fun enough ____ millions of people around the world.', 'attracting', 'attracted', 'to attract', 'attracts', 'C', '形 + enough + to do 表「有趣到足以吸引……」,空处用 to do。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'After the marathon, she was too exhausted even ____.', 'walking', 'walked', 'walks', 'to walk', 'D', 'too + 形 + to do 表「太累以致连走都走不动」,空处用 to do。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The young player trained hard enough ____ a place on the top team.', 'to win', 'winning', 'won', 'wins', 'A', '副 + enough + to do 表「足够努力以致赢得席位」,空处用 to do。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The watch band is adjustable enough ____ almost any wrist.', 'fitting', 'to fit', 'fitted', 'fits', 'B', '形 + enough + to do 表「足够可调以致适合……」,空处用 to do。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'He ran so fast as ____ all the other runners far behind.', 'leaving', 'left', 'to leave', 'leaves', 'C', 'so + 副 + as to do 表「如此快以致把别人甩在后面」,空处用 to do。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The plank looks easy, but it is hard enough ____ your core muscles.', 'developing', 'developed', 'develops', 'to develop', 'D', '形 + enough + to do 表「足够吃力以致能锻炼……」,空处用 to do。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'She was strong enough ____ her whole body on the bar for a minute.', 'to hold', 'holding', 'held', 'holds', 'A', '形 + enough + to do 表「足够强壮以致能支撑身体」,空处用 to do。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The match was so exciting as ____ everyone on the edge of their seats.', 'keeping', 'to keep', 'kept', 'keeps', 'B', 'so + 形 + as to do 表「如此精彩以致让所有人紧张」,空处用 to do。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'It was too cold ____ outside, so we trained in the gym instead.', 'training', 'trained', 'to train', 'trains', 'C', 'too + 形 + to do 表「太冷以致不能在外训练」,空处用 to do。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'At sixteen he was old enough ____ in the under-18 race.', 'competing', 'competed', 'competes', 'to compete', 'D', '形 + enough + to do 表「足够大可以参赛」,空处用 to do。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The gorilla suit was too hot ____ comfortably during the long run.', 'to wear', 'wearing', 'worn', 'wears', 'A', 'too + 形 + to do 表「太热以致穿着不舒服」,空处用 to do。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'Her lungs grew strong enough ____ in national competitions.', 'running', 'to run', 'ran', 'runs', 'B', '形 + enough + to do 表「足够强健以致能参赛跑步」,空处用 to do。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The rules are simple enough for a child ____ in a few minutes.', 'learning', 'learned', 'to learn', 'learns', 'C', 'enough + for sb + to do 表「简单到孩子也能学会」,空处用 to do。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'He was too nervous before the final ____ anything at all.', 'eating', 'ate', 'eats', 'to eat', 'D', 'too + 形 + to do 表「太紧张以致什么也吃不下」,空处用 to do。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The skipping rope is light enough ____ in any small pocket.', 'to carry', 'carrying', 'carried', 'carries', 'A', '形 + enough + to do 表「足够轻以致能装进口袋」,空处用 to do。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'The team played so well as ____ the championship that very year.', 'winning', 'to win', 'won', 'wins', 'B', 'so + 副 + as to do 表「踢得如此好以致赢得冠军」,空处用 to do。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'My legs ached too much ____ another lap of the track.', 'running', 'ran', 'to run', 'runs', 'C', 'too + 副 + to do 表「太痛以致再也跑不动一圈」,空处用 to do。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.02'), 'Tai chi is gentle enough for older people ____ every morning.', 'practising', 'practised', 'practises', 'to practise', 'D', '形 + enough + for sb + to do 表「温和到老人也能每天练」,空处用 to do。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'Every morning she goes to the park ____ tai chi with a master.', 'to practise', 'practising', 'practised', 'practises', 'A', 'to do 在此表目的(为了练太极而去公园);限定式/分词不能作目的状语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'He downloaded a fitness app ____ his progress against his friends.', 'charting', 'to chart', 'charted', 'charts', 'B', 'to do 表目的(下载应用是为了记录进展),空处用不定式。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'The watch is light enough ____ all day without any trouble.', 'wearing', 'worn', 'to wear', 'wears', 'C', 'enough + to do 表结果(轻到可以戴一整天),空处用不定式。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'She joined an athletics club ____ her weak lungs stronger.', 'making', 'made', 'makes', 'to make', 'D', 'to do 表目的(加入俱乐部是为了让肺更强健),空处用不定式。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'He gets up at five ____ for two hours before going to work.', 'to train', 'training', 'trained', 'trains', 'A', 'to do 表目的(早起是为了训练),空处用不定式。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'The game is simple enough ____ anywhere with just a cheap ball.', 'playing', 'to play', 'played', 'plays', 'B', 'enough + to do 表结果(简单到随处可玩),空处用不定式。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'Many people travel to Yangshuo ____ tai chi from a great master.', 'learning', 'learned', 'to learn', 'learns', 'C', 'to do 表目的(去阳朔是为了学太极),空处用不定式。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'On that day the soldiers put down their guns ____ football together.', 'playing', 'played', 'plays', 'to play', 'D', 'to do 表目的(放下枪是为了一起踢球),空处用不定式。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'He was too stressed after work ____ well at night.', 'to sleep', 'sleeping', 'slept', 'sleeps', 'A', 'too + 形 + to do 表结果(太焦虑以致睡不好),空处用不定式。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'She wears a smart watch ____ her heart rate during exercise.', 'monitoring', 'to monitor', 'monitored', 'monitors', 'B', 'to do 表目的(戴手表是为了监测心率),空处用不定式。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'These exercises are gentle enough ____ at home without a coach.', 'doing', 'done', 'to do', 'does', 'C', 'enough + to do 表结果(温和到可以在家做),空处用不定式。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'He runs every evening ____ the stress of a busy working day.', 'escaping', 'escaped', 'escapes', 'to escape', 'D', 'to do 表目的(跑步是为了摆脱压力),空处用不定式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'The race was so tiring as ____ his legs aching for several days.', 'to leave', 'leaving', 'left', 'leaves', 'A', 'so + 形 + as to do 表结果(累到让腿痛了好几天),空处用不定式。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'She practised hard every single day ____ the school champion.', 'becoming', 'to become', 'became', 'becomes', 'B', 'to do 表目的(刻苦练习是为了成为校冠军),空处用不定式。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'The running app was fun enough ____ him going for many months.', 'keeping', 'kept', 'to keep', 'keeps', 'C', 'enough + to do 表结果(有趣到让他坚持了好几个月),空处用不定式。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'He wore a gorilla suit ____ money for the world''s last gorillas.', 'raising', 'raised', 'raises', 'to raise', 'D', 'to do 表目的(穿大猩猩服是为了筹款),空处用不定式。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'Tai chi is slow enough for anyone ____ , whatever their age.', 'to enjoy', 'enjoying', 'enjoyed', 'enjoys', 'A', 'enough + for sb + to do 表结果(慢到任何人都能享受),空处用不定式。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'We use bar charts ____ how something changes over time.', 'showing', 'to show', 'showed', 'shows', 'B', 'to do 表目的(用条形图是为了展示变化),空处用不定式。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'He trained hard enough ____ a place in the national team.', 'earning', 'earned', 'to earn', 'earns', 'C', 'enough + to do 表结果(足够努力以致赢得国家队席位),空处用不定式。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U3' AND code='f2u3.03'), 'She started running ____ her doctor''s advice about her asthma.', 'following', 'followed', 'follows', 'to follow', 'D', 'to do 表目的(开始跑步是为了听从医生的建议),空处用不定式。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Game for the World', 'These days, football is one of the most popular sports on the planet. The game is very old: it goes back over two thousand years to ancient China, where it was known as cuju. Players kicked a ball made of animal skin towards goals hung in the air. The football we know today, however, took shape in Great Britain, where the game was given a clear set of rules. Why has it spread to almost every country? One reason is that it is a simple game to play and needs very little equipment. Even the ball does not have to be expensive; children everywhere play happily with a ball made of plastic bags. Another reason is the excitement on the field. You do not have to be a fan to enjoy watching skilful players pass, score and defend. Football also brings people together, breaking down walls between strangers and even, for one famous moment in 1914, between soldiers at war.', '说明·足球为何风靡全球', 160, '[{"q":"Where did the modern form of football develop its rules?","answer":"A","options":["In Great Britain.","In ancient China.","On the Moon.","In Germany."],"explanation":"原文说现代足球在英国成形并被定下明确规则;其余为相反或未提。"},{"q":"According to the text, why can poor children still enjoy football?","answer":"B","options":["It must be played inside a big stadium.","It needs very little equipment, and a cheap ball will do.","It requires very expensive shoes.","It can only be played in Britain."],"explanation":"原文指出足球器材需求很少、塑料袋做的球就能玩,是对此的转述。"},{"q":"What does the example from 1914 mainly show?","answer":"A","options":["Football can bring together even people who are enemies.","Football was first invented during a war.","Soldiers preferred fighting to playing games.","Football''s rules were changed in 1914."],"explanation":"1914 年敌对士兵一起踢球说明足球能让人团结,是对该例子作用的概括。"}]'::jsonb, '[{"word":"equipment","cn":"装备"},{"word":"plastic","cn":"塑料制的"},{"word":"defend","cn":"防守"},{"word":"soldier","cn":"士兵"}]'::jsonb, 2, 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Watch for Every Athlete', 'Are you looking for a watch that can help you keep track of your fitness? Whether you are a professional athlete or simply a keen beginner, the new DX Sports Watch may be the ideal choice for you. The watch has a bright digital display that records your steps, speed and distance. At the same time, it can monitor your heart rate and the number of calories you burn during exercise. A clever voice-control setting lets you change the screen without using your hands, so you can stay focused on your training. Because the soft band is waterproof and fully adjustable, the watch stays comfortable even on a long, sweaty run. It also helps you chart your training progress week by week, so you can clearly see how far you have come. The DX Sports Watch is available online only, so visit our website and place your order today.', '应用文·运动手表广告', 149, '[{"q":"Who is the DX Sports Watch made for?","answer":"B","options":["Only professional athletes.","Both professional athletes and keen beginners.","Only doctors and nurses.","Only swimmers."],"explanation":"原文说无论是专业运动员还是热心的初学者都适用,是对适用人群的转述。"},{"q":"What allows you to use the watch without your hands?","answer":"C","options":["A much larger screen.","A printed paper manual.","A voice-control setting.","A second spare band."],"explanation":"原文指出语音控制功能让人无须用手操作,是对该功能的概括。"},{"q":"How can buyers get the watch?","answer":"D","options":["From any local shop.","Only as a free gift.","By calling a phone number.","By ordering it online."],"explanation":"原文说手表只在网上有售,是对购买方式的转述。"}]'::jsonb, '[{"word":"display","cn":"显示屏"},{"word":"monitor","cn":"监测"},{"word":"adjustable","cn":"可调节的"},{"word":"available","cn":"可买到的"}]'::jsonb, 2, 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Leah and Tai Chi', 'Chinese martial arts are famous all over the world, and every year thousands of people travel to China to study them. One of the most popular choices is tai chi, an art with a very long history. Tai chi involves a series of slow, gentle movements that are meant to relax the mind and calm the body. Leah, a journalist from Britain, first became interested in tai chi after taking a few classes at home. Later she moved to the small town of Yangshuo, where a respected master lives among beautiful hills and rivers. Learning tai chi has not always been easy for her. She has had to get used to early mornings, practise the same basic movements again and again, and even learn some Chinese. Yet she says the art brings her a deep sense of balance and peace. For Leah, tai chi is a simple way to relax, to stay healthy, and to feel more at home in China.', '记叙·外国人学太极', 161, '[{"q":"Why did Leah move to Yangshuo?","answer":"A","options":["To study under a respected tai chi master there.","To open her own tai chi school.","To work there as a tour guide.","To get away from early mornings."],"explanation":"原文说阳朔住着一位受人尊敬的大师,她搬去是为了跟他学,是对原因的转述。"},{"q":"What has been difficult for Leah?","answer":"B","options":["Finding a place to live in town.","Getting up early and repeating the same movements.","Paying for her tai chi classes.","Understanding the local weather."],"explanation":"原文列出早起、反复练同样动作等困难,是对此的概括。"},{"q":"How does Leah feel about tai chi now?","answer":"C","options":["It is too slow to be of any use.","It has made her tired of living in China.","It leaves her feeling calm and well balanced inside.","It is only suitable for old people."],"explanation":"原文说太极带给她平衡与平静,是对她感受的转述。"}]'::jsonb, '[{"word":"involve","cn":"包含"},{"word":"master","cn":"大师"},{"word":"balance","cn":"平衡"}]'::jsonb, 2, 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Running into a Better Life', 'Li Yue, who is sixteen and lives in Beijing, was born with asthma and never imagined she could become a runner. She only joined her local athletics club because a doctor told her that, in her case, gentle exercise might improve the way her lungs worked. To her surprise, she soon found herself taking part in small local races. As her health and her running both improved, she began to enter larger national competitions. This year she won a silver medal in the under-18 10,000 metres, and she now dreams of winning gold next season. Li Yue says that running has done far more than make her fit. It has given her confidence and led her to achieve things she once thought were impossible. Her advice to others is simple: start with small steps, keep going, and never let an illness decide what you can or cannot do.', '记叙·带哮喘的跑者', 148, '[{"q":"Why did Li Yue first join the athletics club?","answer":"D","options":["She wanted to win medals from the start.","Her friends forced her to take part.","She disliked staying at home alone.","Her doctor suggested that exercise might help her lungs."],"explanation":"原文说医生告诉她锻炼可能改善肺功能,所以她才加入,是对原因的转述。"},{"q":"What has running given Li Yue besides fitness?","answer":"A","options":["Confidence and a belief that she can achieve more.","A large amount of money.","A brand-new job in Beijing.","A complete cure for every illness."],"explanation":"原文说跑步给了她信心、让她做到曾以为不可能的事,是对此的概括。"},{"q":"What is Li Yue''s advice to others?","answer":"B","options":["Only run if you are already perfectly healthy.","Begin small, keep going, and don''t let illness limit you.","Give up as soon as it becomes hard.","Train alone and avoid all races."],"explanation":"原文建议从小步开始、坚持下去、别让疾病决定一切,是对原句的转述。"}]'::jsonb, '[{"word":"asthma","cn":"哮喘"},{"word":"lung","cn":"肺"}]'::jsonb, 2, 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Great Gorilla Run', 'David, a fifty-two-year-old computer engineer from New York, has a rather unusual way of dealing with stress. His job is full of new challenges, and at times it makes him feel anxious. To clear his mind, he goes running as often as he can. By the end of a run, he says, his worries seem to disappear and he feels ready for the next day. This year David did something especially strange: he entered the Great Gorilla Run in London. The event raises money to protect the world''s last wild gorillas. Every runner has to wear a furry gorilla suit, which is hot and sweaty, and David''s legs ached badly by the finish. Even so, he had a wonderful time. The funniest moment came when someone in the crowd offered him a banana, a perfect treat, he joked, for a running gorilla. David enjoyed a great day out and felt proud to help save real gorillas at the same time.', '记叙·大猩猩慈善跑', 160, '[{"q":"How does David usually deal with stress from work?","answer":"C","options":["He sleeps for much longer.","He changes his job often.","He goes running whenever he can.","He avoids all kinds of exercise."],"explanation":"原文说他尽量多跑步来理清思绪,是对解压方式的转述。"},{"q":"What is special about the Great Gorilla Run?","answer":"D","options":["It is only open to computer engineers.","Runners must each carry a banana.","It takes place in New York.","Runners wear gorilla suits to raise money for wild gorillas."],"explanation":"原文说每位跑者穿大猩猩服、为保护野生大猩猩筹款,是对其特别之处的概括。"},{"q":"How did David feel about the day overall?","answer":"A","options":["He had a great time and was proud to help.","He regretted ever taking part.","He found the whole event boring.","He was angry about the heavy suit."],"explanation":"原文说他度过愉快的一天并为帮助大猩猩而自豪,是对整体感受的转述。"}]'::jsonb, '[{"word":"disappear","cn":"消失"},{"word":"gorilla","cn":"大猩猩"},{"word":"sweaty","cn":"满是汗的"},{"word":"ache","cn":"作痛"}]'::jsonb, 2, 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Exercises You Can Do Anywhere', 'You do not need a gym or expensive equipment to keep fit. Some of the best exercises can be done almost anywhere, using only your own body or a simple rope. The plank, for example, asks you to keep your body very still. It looks easy, but it builds your core muscles and strengthens your lower back. Push-ups develop the muscles in your chest and shoulders, as long as you remember to keep your back straight. With just a rope, skipping improves your footwork and balance, is good for your heart, and burns plenty of calories without you going anywhere. If you can find a bar that supports your weight, pull-ups build real strength in your upper body, especially in the arms. Even simple jogging helps your heart and lungs and builds strong leg bones. The best plan is to mix several of these exercises through the week, so that every part of the body gets a turn.', '说明·随处可做的健身', 158, '[{"q":"What does the plank mainly train?","answer":"B","options":["The leg bones only.","The core muscles and the lower back.","Mainly the footwork.","The chest and shoulders."],"explanation":"原文说平板支撑锻炼核心肌群、强化下背部,是对其作用的转述。"},{"q":"What is one benefit of skipping?","answer":"C","options":["It needs a heavy machine to work.","It only trains the arms.","It improves footwork and balance and burns calories.","It must always be done outdoors."],"explanation":"原文说跳绳改善脚法和平衡、燃烧热量,是对好处的概括。"},{"q":"What is the writer''s main advice?","answer":"D","options":["Only ever do a single exercise.","Always train inside a gym.","Avoid jogging completely.","Combine several body-weight exercises across the week."],"explanation":"原文建议一周内混合做几种练习,是对中心建议的转述。"}]'::jsonb, '[{"word":"plank","cn":"平板支撑"},{"word":"balance","cn":"平衡"},{"word":"bar","cn":"横杆"},{"word":"upper","cn":"上面的"},{"word":"bone","cn":"骨头"}]'::jsonb, 2, 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'A Ball Made of Plastic Bags', 'When Tiago was a boy, his family was poor and could not (1)____ a real football. That did not stop him. He made his own ball out of old (2)____ bags tied tightly together. Every evening after school he ran out to a dusty field to (3)____ with his friends. They had no nets, so they used two stones as a (4)____. None of them owned proper boots or any other (5)____, yet they played to their heart''s (6)____ until the sky grew dark. Tiago was small, but he was quick, and he soon learned how to pass and (7)____ better than older boys. People in the town began to say that he was (8)____ enough to join a real club one day. Years later that dream came true, and Tiago became a local (9)____. He still tells children that you do not need money to (10)____ the game you love.', 151, 2, '[{"q":"1","answer":"A","options":["afford","win","watch","throw"],"explanation":"could not afford「买不起」,符合家里贫穷的语境。"},{"q":"2","answer":"B","options":["wooden","plastic","metal","stone"],"explanation":"用旧塑料袋做球,只有 plastic bags 说得通。"},{"q":"3","answer":"C","options":["sleep","cook","play","study"],"explanation":"跑到球场和朋友一起 play 踢球。"},{"q":"4","answer":"D","options":["prize","master","label","goal"],"explanation":"用两块石头当 goal 球门。"},{"q":"5","answer":"A","options":["equipment","weather","advice","music"],"explanation":"没有球鞋或其他 equipment 器材。"},{"q":"6","answer":"B","options":["money","content","time","rest"],"explanation":"to one''s heart''s content「尽情地」是固定搭配。"},{"q":"7","answer":"C","options":["cry","drive","defend","paint"],"explanation":"学会传球与 defend 防守,符合足球语境。"},{"q":"8","answer":"D","options":["sad","late","cold","good"],"explanation":"good enough to join「好到足以加入」。"},{"q":"9","answer":"A","options":["champion","doctor","teacher","farmer"],"explanation":"梦想成真后成为当地 champion 冠军。"},{"q":"10","answer":"B","options":["hate","play","miss","leave"],"explanation":"不需要钱也能 play 玩你热爱的运动。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'My First Tai Chi Class', 'Last summer I joined a tai chi class in a quiet park near my home. At first I felt (1)____, because everyone else seemed to know the movements. The teacher, an old (2)____ with kind eyes, told me to relax and simply follow him. Tai chi (3)____ a lot of slow, gentle movements, and at the start my arms and legs would (4)____ after only a few minutes. I had to get up (5)____ every morning to practise before work, which was not easy. Little by little, though, I began to find a sense of (6)____ in my body that I had never felt before. My breathing grew (7)____ and my mind became quiet. The early mornings no longer felt like a (8)____. Now I (9)____ tai chi to anyone who feels stressed. It is a simple way to relax your mind and (10)____ your body.', 146, 2, '[{"q":"1","answer":"C","options":["proud","lazy","nervous","rich"],"explanation":"别人都会而自己不会,感到 nervous 紧张。"},{"q":"2","answer":"D","options":["soldier","driver","writer","master"],"explanation":"教太极的老者是 master 大师。"},{"q":"3","answer":"A","options":["involves","forgets","sells","breaks"],"explanation":"tai chi involves「包含」缓慢的动作。"},{"q":"4","answer":"B","options":["sing","ache","jump","smile"],"explanation":"几分钟后手脚就 ache 酸痛。"},{"q":"5","answer":"C","options":["late","slowly","early","loudly"],"explanation":"上班前练习要 early 早起。"},{"q":"6","answer":"D","options":["danger","noise","anger","balance"],"explanation":"身体里找到一种 balance 平衡感。"},{"q":"7","answer":"A","options":["deeper","louder","shorter","faster"],"explanation":"呼吸变得 deeper 更深沉,心也静下来。"},{"q":"8","answer":"B","options":["prize","burden","gift","treat"],"explanation":"早起不再像一种 burden 负担。"},{"q":"9","answer":"C","options":["refuse","forget","recommend","sell"],"explanation":"向有压力的人 recommend 推荐太极。"},{"q":"10","answer":"D","options":["break","lose","drop","calm"],"explanation":"放松心情、calm 让身体平静。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'School Sports Day', 'Our school holds a sports day every spring, and this year I decided to (1)____ in the 800 metres. I had never been a fast runner, so I knew I had to (2)____ hard. For a whole month I got up early to (3)____ around the playground before class. My legs often (4)____ at night, but I did not give up. My PE teacher gave me useful (5)____ on how to breathe and save energy. He also (6)____ me that I was improving, even when I could not feel it myself. On sports day I was so (7)____ that my hands were shaking at the start line. When the race began, I tried to keep a steady (8)____ instead of rushing. To my great joy, I came second and won a silver (9)____. That day taught me that hard training can turn a slow runner into a real (10)____.', 149, 2, '[{"q":"1","answer":"A","options":["compete","sleep","watch","refuse"],"explanation":"decided to compete「决定参赛」跑 800 米。"},{"q":"2","answer":"B","options":["rest","train","eat","relax"],"explanation":"跑得不快,所以必须刻苦 train 训练。"},{"q":"3","answer":"C","options":["swim","drive","run","sleep"],"explanation":"早起在操场上 run 跑步。"},{"q":"4","answer":"D","options":["smiled","sang","danced","ached"],"explanation":"晚上腿常常 ached 酸痛。"},{"q":"5","answer":"A","options":["advice","money","food","music"],"explanation":"老师给了有用的 advice 建议。"},{"q":"6","answer":"B","options":["warned","assured","forced","stopped"],"explanation":"assured me that「向我保证」我在进步。"},{"q":"7","answer":"C","options":["lazy","proud","nervous","bored"],"explanation":"so nervous that「太紧张以致」手发抖。"},{"q":"8","answer":"D","options":["price","prize","place","pace"],"explanation":"保持稳定的 pace 节奏而不冲刺。"},{"q":"9","answer":"A","options":["medal","ticket","letter","photo"],"explanation":"得第二名,赢得一枚银 medal 奖牌。"},{"q":"10","answer":"B","options":["beginner","champion","stranger","farmer"],"explanation":"刻苦训练能把慢跑者变成真正的 champion 冠军。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'My First Marathon', 'I had jogged for fun for years, but I had never run a (1)____ until last autumn. When I signed up, friends warned me that 42 kilometres was a long (2)____ for a beginner. They were right. For months I trained almost every day to build up my (3)____. On the morning of the race I felt both excited and (4)____. The first half went well, and I kept a comfortable (5)____. After 30 kilometres, however, my legs began to (6)____ badly and my energy seemed to (7)____. I wanted to stop, but the cheering crowd gave me the (8)____ to keep going. Slowly, step by step, I reached the finish line. I did not win any (9)____, but crossing that line felt like the greatest (10)____ of my life. Now I tell everyone that the real winner is anyone who refuses to give up.', 145, 2, '[{"q":"1","answer":"C","options":["lesson","meeting","marathon","meal"],"explanation":"从未跑过一次 marathon 马拉松。"},{"q":"2","answer":"D","options":["story","season","message","distance"],"explanation":"42 公里对新手是很长的 distance 距离。"},{"q":"3","answer":"A","options":["fitness","money","homework","traffic"],"explanation":"天天训练来增强 fitness 体能。"},{"q":"4","answer":"B","options":["bored","nervous","sleepy","angry"],"explanation":"既兴奋又 nervous 紧张。"},{"q":"5","answer":"C","options":["price","plate","pace","prize"],"explanation":"保持舒适的 pace 配速。"},{"q":"6","answer":"D","options":["shine","laugh","grow","ache"],"explanation":"30 公里后腿开始剧烈 ache 酸痛。"},{"q":"7","answer":"A","options":["disappear","increase","return","appear"],"explanation":"体力似乎要 disappear 耗尽消失。"},{"q":"8","answer":"B","options":["money","power","ticket","bill"],"explanation":"观众的欢呼给了我坚持下去的 power 力量。"},{"q":"9","answer":"C","options":["ticket","letter","medal","key"],"explanation":"我没赢得任何 medal 奖牌。"},{"q":"10","answer":"D","options":["mistake","accident","problem","achievement"],"explanation":"冲线像是人生最大的 achievement 成就。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'Running with an App', 'A few years ago I did almost no exercise. Then a friend told me about a running (1)____ called Running Power. The app shows your performance against other runners in your social (2)____. At first I only ran to see my own name climb to the (3)____ of the list. Slowly, something changed. I realised I was not (4)____: many other people in my area were running for the same (5)____. We began to share routes and (6)____ each other to do better. Running soon helped me deal with the (7)____ of a busy week, and after each run my worries seemed to (8)____. The app also let me (9)____ my progress, so I could see how much faster I had become. In the end I stopped using the app, but by then I had completely fallen in (10)____ with running.', 141, 2, '[{"q":"1","answer":"A","options":["app","book","song","meal"],"explanation":"一款跑步 app 应用,符合下文 the app。"},{"q":"2","answer":"B","options":["garden","network","kitchen","forest"],"explanation":"social network「社交网络」里的其他跑者。"},{"q":"3","answer":"C","options":["floor","corner","top","gate"],"explanation":"想看到名字爬到榜单的 top 顶端。"},{"q":"4","answer":"D","options":["ready","late","asleep","alone"],"explanation":"意识到自己并不 alone 孤单。"},{"q":"5","answer":"A","options":["reason","price","ticket","meal"],"explanation":"别人为同样的 reason 理由而跑。"},{"q":"6","answer":"B","options":["forbid","encourage","ignore","blame"],"explanation":"分享路线、互相 encourage 鼓励。"},{"q":"7","answer":"C","options":["music","weather","tension","colour"],"explanation":"帮我应对忙碌一周的 tension 压力。"},{"q":"8","answer":"D","options":["grow","return","increase","disappear"],"explanation":"跑完后烦恼似乎 disappear 消失。"},{"q":"9","answer":"A","options":["chart","hide","lose","waste"],"explanation":"App 让我 chart 记录跟踪进展。"},{"q":"10","answer":"B","options":["trouble","love","danger","sleep"],"explanation":"fall in love with「爱上」跑步。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U3', 'From Skating to Ice Hockey', 'Only three years ago, I was (1)____ of sports like skiing and skating. To deal with this fear, I decided to (2)____ a skating club. At first I really envied the other members, who looked so (3)____ on the ice. My teacher, however, was patient and kind, and before I knew it I was able to (4)____ without falling. He then gently (5)____ me to try ice hockey, and I agreed. I loved it at once. Soon I was (6)____ with my local team almost every evening, even though my body often (7)____ afterwards. Last winter I felt so (8)____ when our team won the regional competition. It made me believe I could (9)____ almost anything. We are now training for the national games, but my (10)____ goal is to become an ice hockey coach and help others learn this wonderful sport.', 142, 2, '[{"q":"1","answer":"C","options":["proud","fond","afraid","sure"],"explanation":"afraid of「害怕」滑雪滑冰,与下文 this fear 一致。"},{"q":"2","answer":"D","options":["leave","close","sell","join"],"explanation":"决定 join 加入滑冰俱乐部。"},{"q":"3","answer":"A","options":["confident","tired","afraid","bored"],"explanation":"羡慕别人在冰上很 confident 自信。"},{"q":"4","answer":"B","options":["swim","skate","drive","fly"],"explanation":"学会 skate 滑冰而不摔倒。"},{"q":"5","answer":"C","options":["refused","prevented","persuaded","forbade"],"explanation":"persuaded me to try「说服我尝试」,与 I agreed 一致。"},{"q":"6","answer":"D","options":["sleeping","eating","shopping","training"],"explanation":"几乎每晚和队伍一起 training 训练。"},{"q":"7","answer":"A","options":["ached","smiled","relaxed","rested"],"explanation":"训练后身体常常 ached 酸痛。"},{"q":"8","answer":"B","options":["sad","proud","angry","calm"],"explanation":"夺得地区冠军时感到 proud 自豪。"},{"q":"9","answer":"C","options":["lose","miss","achieve","drop"],"explanation":"让我相信几乎能 achieve 实现一切。"},{"q":"10","answer":"D","options":["broken","empty","false","ultimate"],"explanation":"我的 ultimate 最终目标是成为冰球教练。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Choosing a Sport to Try', '外研社版必修第二册 U3 · dialogue', 3, 'Mia: Hi Tom, our school is starting some new sports clubs. Which one will you join?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Why Skipping Is Great', '外研社版必修第二册 U3 · passage', 2, 'Skipping is one of the cheapest and most useful exercises you can do. All you need is a simple rope, and you can do it almost anywhere, in a park, a yard, or even your bedroom. Skipping is very good for your heart, and it helps you burn a lot of calories in just a few minutes. It also improves your footwork and your balance, which is useful for almost every other sport. Best of all, a rope costs very little, so skipping is a sport that everyone can afford.', '跳绳是最便宜也最有用的运动之一。只需一根简单的绳子,你几乎在任何地方都能跳:公园、院子,甚至卧室。跳绳对心脏很好,几分钟就能燃烧大量热量。它还能改善脚法和平衡,这对几乎所有其他运动都有用。最棒的是绳子很便宜,所以人人都跳得起。', 'uk_female', '[{"q":"What do you need in order to skip?","type":"choice","answer":"D","options":["A large machine.","A swimming pool.","A pair of skates.","Just a simple rope."]},{"q":"Where can you skip?","type":"choice","answer":"A","options":["Almost anywhere.","Only in a gym.","Only outdoors.","Only at school."]},{"q":"What does skipping improve besides the heart?","type":"choice","answer":"B","options":["Reading and writing.","Footwork and balance.","Eyesight.","Memory."]},{"q":"How long does it take to burn many calories?","type":"choice","answer":"C","options":["Several hours.","A whole day.","Just a few minutes.","About one week."]},{"q":"Why can everyone do skipping?","type":"choice","answer":"D","options":["It needs no movement at all.","It is taught in every school.","It requires a personal coach.","A rope costs very little."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Interview with a Tai Chi Learner', '外研社版必修第二册 U3 · dialogue', 3, 'Journalist: Leah, when did you first become interested in tai chi?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Sara''s Running Story', '外研社版必修第二册 U3 · passage', 2, 'My name is Sara, and two years ago I almost never exercised. One day my doctor told me that running could make my lungs stronger, so I joined a small club. At first even one lap left me out of breath. But I kept going, and slowly my body grew stronger. Last month I ran my first five-kilometre race and finished with a big smile. Running has given me energy, confidence, and many new friends. If you think you are too weak to run, please believe me: you can do far more than you imagine.', '我叫 Sara,两年前我几乎从不锻炼。有一天医生告诉我跑步能让肺更强健,于是我加入了一个小俱乐部。起初连跑一圈都气喘吁吁,但我坚持下来,身体慢慢变强。上个月我跑完了人生第一个五公里赛,笑着冲过终点。跑步给了我能量、自信和许多新朋友。如果你觉得自己太弱跑不动,请相信我:你能做到的远比想象的多。', 'uk_female', '[{"q":"Why did Sara start running?","type":"choice","answer":"B","options":["She wanted to win prizes.","Her doctor said it could strengthen her lungs.","Her friends made her do it.","She was already an athlete."]},{"q":"How did she feel during her first laps?","type":"choice","answer":"C","options":["Completely relaxed.","Very bored.","Out of breath.","Quite angry."]},{"q":"What did she do last month?","type":"choice","answer":"D","options":["She won a gold medal.","She stopped running for good.","She joined a football team.","She ran her first five-kilometre race."]},{"q":"What has running given her?","type":"choice","answer":"A","options":["Energy, confidence and new friends.","A great deal of money.","A brand-new house.","A fast car."]},{"q":"What is Sara''s message to weak people?","type":"choice","answer":"B","options":["They should never try to run.","They can do more than they think.","Running is always dangerous.","Only athletes should exercise."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Recommending a Sport for PE Class', '外研社版必修第二册 U3 · dialogue', 3, 'Ken: For our PE class, I''d like to recommend basketball. What do you think, Lucy?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Dragon Boat Racing', '外研社版必修第二册 U3 · passage', 2, 'Dragon boat racing is one of China''s oldest and most exciting team sports. A long, narrow boat is shaped like a dragon, and a team of paddlers sits inside it. To move fast, every paddler must pull at exactly the same time, while a drummer beats out the rhythm. The sport needs great strength, but even more it needs teamwork, because one person alone can do nothing. Each summer, thousands of people gather by the rivers to watch the colourful boats race. For many teams, the real prize is not winning, but the joy of working together as one.', '赛龙舟是中国最古老、最激动人心的团队运动之一。一条又长又窄的船被做成龙的样子,一队桨手坐在里面。要划得快,每位桨手必须在完全相同的时刻发力,而鼓手敲出节奏。这项运动需要很大的力量,但更需要团队合作,因为一个人单独什么也做不成。每年夏天,成千上万的人聚在河边观看五彩的龙舟竞渡。对许多队伍来说,真正的奖赏不是夺冠,而是齐心协力的快乐。', 'uk_female', '[{"q":"What is a dragon boat shaped like?","type":"choice","answer":"D","options":["A fish.","A car.","A bird.","A dragon."]},{"q":"What must every paddler do?","type":"choice","answer":"A","options":["Pull at exactly the same time.","Sing loudly together.","Stand up in the boat.","Row completely alone."]},{"q":"What does the drummer do?","type":"choice","answer":"B","options":["Steers the boat.","Beats out the rhythm.","Counts the crowd.","Sells the tickets."]},{"q":"What does the sport need most?","type":"choice","answer":"C","options":["Expensive boats.","Good weather only.","Teamwork.","A large stadium."]},{"q":"For many teams, what is the real prize?","type":"choice","answer":"D","options":["A large cash reward.","A golden cup.","Fame on television.","The joy of working together."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U3', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Personal Sports Story(写一篇个人运动故事)', 'My Sports Story', '假设你叫李华,一个运动爱好者网站正在征集能激励读者的个人运动故事。请用英语写一篇约100词的短文,内容包括:① 你做的是什么运动、当初是怎么开始的;② 你对这项运动的感受;③ 你为提高所做的努力,以及未来的目标。注意:试着用上不定式(如 a sport to enjoy / too tired to give up / trained hard enough to win)。', 'Suppose you are Li Hua. A website for sports lovers is collecting personal stories to inspire its readers. Write a short passage (about 100 words) including: 1) what sport you do and how you got started; 2) how you feel about it; 3) what you have done to improve and your goal for the future. Try to use to-infinitives (e.g. a sport to enjoy, too tired to give up, trained hard enough to win).', '["如何开始(When I was younger… / I never thought I''d…)","你的感受(Before I knew it, I had fallen in love with…)","为提高所做的努力 + 用上不定式(I trained hard enough to…)","未来目标(My ultimate goal is to…)"]'::jsonb, 70, 100, 'When I was younger, I never thought I would be a runner. I had asthma, and even one lap was too hard for me to finish. Then a doctor told me that gentle exercise might make my lungs stronger, so I joined a small club. Before I knew it, I had fallen in love with running. I got up early every day to train, and slowly I grew strong enough to enter real races. Last month I won a medal at our city race. My ultimate goal is to run a marathon. If you feel too weak to start, please don''t give up!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["When I was younger, I never thought I would be a runner.","Even one lap was too hard for me to finish.","I got up early every day to train, and slowly I grew strong enough to enter real races.","My ultimate goal is to run a marathon."]'::jsonb, '[{"wrong":"It was too hard to me to finish.","correct":"It was too hard for me to finish.","note":"too…to 结构中动作者用 for sb,不用 to sb。"},{"wrong":"I was strong enough win the race.","correct":"I was strong enough to win the race.","note":"enough to do 中 to 不能省略。"},{"wrong":"I got up early to training.","correct":"I got up early to train.","note":"表目的用 to do(动词原形),不用 to + -ing。"}]'::jsonb, '【个人运动故事结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U3', '{"title":"不定式作定语和结果状语(to do)速查","intro":"to do 既能放在名词后作定语(表示''要做/可做的…''),也能作状语表结果(too…to / enough to / so…as to)或目的(= in order to)。判断口诀:跟在名词后→定语;跟在 too/enough/so…as 后→结果;表示''为了''→目的。这三种情况空里都填 to do。","table":{"headers":["结构","用法 / 例句"],"rows":[["名词/不定代词 + to do","作定语:a game to play(可玩的游戏)、something to eat(吃的东西)"],["the first/last/only + 名词 + to do","作定语:the first player to score(第一个进球的人)"],["too + 形/副 + to do","作结果状语:too tired to continue(太累以致不能继续)"],["形/副 + enough + to do","作结果状语:strong enough to win(足够强以致能赢)"],["so + 形/副 + as to do","作结果状语:so fast as to leave others behind(快到把别人甩开)"],["to do(= in order to)","作目的状语:get up early to train(早起去训练)"]]},"specialRules":[{"rule":"定语的 to do 与前面名词常是动宾关系:a book to read = read a book","mark":"water to drink / a sport to recommend"},{"rule":"too…to 中若有动作者用 for sb;to 后动词不能省","mark":"too hard for me to finish √"},{"rule":"enough 放在形容词/副词之后、名词之前;enough to do 的 to 不能省","mark":"strong enough to… √ / enough strong ×"},{"rule":"so + adj/adv + as to do ≈ so…that 从句,但更正式简洁","mark":"so kind as to help = so kind that he helped"}],"why":["to do 本身没有时态、没有人称,所以无论作定语、目的还是结果,空里都用''to + 动词原形'';-ing/-ed/限定式承担别的成分,不能顶替这个不定式。"],"gaokaoPoints":["语法填空/词形变化:名词后或 too…/enough/so…as 后,把动词写成 to do。","辨析 to do(目的/结果)与 -ing(主动/进行)、-ed(被动/完成)在状语和定语中的分工。","too…to(否定结果)与 …enough to(肯定结果)、so…as to 的相互改写。"],"examVsReal":[{"exam":"a simple game to play(考试/书面定语)","real":"a game that''s easy to play / a game you can play","note":"考试爱用 to do 后置定语;口语常拆成从句或加 you can"},{"exam":"He was too tired to go on.(考试结果状语)","real":"He was so tired he just stopped.","note":"考试用 too…to;口语更常用 so…(that)从句直接说"}]}'::jsonb, 'fltrp');
